// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 count) public {
        vm.assume(count > 0 && count <= 100);
        uint256 deposited = 0;
        for (uint256 i = 0; i < count; i++) {
            vm.deal(address(0x1234), 1 ether);
            vm.prank(address(0x1234));
            (bool success,) = address(c).call{value: 1 ether}("");
            if (success) {
                deposited++;
            }
        }
        assertEq(c.depositsCount(), deposited);
    }
}
